def transform(grid):
    from collections import Counter
    bg = grid[0][0]
    # Locate the black template rectangle.
    rows = [r for r, row in enumerate(grid) if row.count(0) >= 3]
    top, bottom = min(rows), max(rows)
    cols = [c for c in range(len(grid[0])) if grid[top][c] == 0]
    left, right = min(cols), max(cols)
    out = [row[left:right+1] for row in grid[top:bottom+1]]

    # Count connected objects of each color outside the template.
    seen = set()
    counts = Counter()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if top <= r <= bottom and left <= c <= right:
                continue
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if (0 <= yy < len(grid) and 0 <= xx < len(grid[0])
                            and (yy, xx) not in seen
                            and not (top <= yy <= bottom and left <= xx <= right)
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            counts[color] += 1

    for r in range(len(out)):
        color = out[r][1] if len(out[r]) > 1 else bg
        if color != 0:
            for i in range(counts[color]):
                c = 1 + 2*i
                if c < len(out[r]):
                    out[r][c] = color
    return out
